INSERT INTO himnos (id, title, description, musical_note, paragraphs, chorus, filename)
VALUES
('0419cc77-146f-de73-460d-e3696f9a9cd8', $a$LA HERMOSA VISIÓN DE LA CRUZ$a$, $a$Largos años vague por el valle del mal, sin cons$a$, $a$A|La$a$, $a$[{"id": "f87d0cd9-9269-720f-325d-1e3c5e6288d6", "paragraph": "Largos años vague\npor el valle del mal,\nsin consuelo, sin fe, sin amor\n\nY la sombra fatal\nde la senda que hollé,\npuso en mi alma la hiel del dolor.", "chorusPos": [[1]]}, {"id": "7fe5a351-f02e-f39c-9c71-ab3400d14bc3", "paragraph": "Desde entonces, por Él,\nya no soy lo que fui,\nuna sombra sin Dios y sin ley.\n\nMi existencia le di,\ny le quiero ser fiel;\nme constriñe el amor de mi Rey.", "chorusPos": [[1]]}, {"id": "b921f8d6-ec35-283f-732c-cb5b687926dc", "paragraph": "Peregrino que vais\npor el valle del mal,\nvuestra senda solo es de dolor\n\nEsa carga fatal\nque en el alma lleváis,\nven y ponla a los pies del Señor.", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "A mis pies el infierno se abrió,\ny clamé con el alma a Jesús.\nY al instante la escena cambió,\nen la hermosa visión de la cruz.", "id": "b6178953-51f2-dc81-1aab-5dd55b2f2a5a"}]$a$::jsonb, $a$LA HERMOSA VISIÓN DE LA CRUZ.json$a$),
('46b597ca-829a-44e1-9c1c-638c98326034', $a$HAY UNA PROMESA EN LA BIBLIA$a$, $a$/Hay una promesa en la Biblia   Q...$a$, $a$--$a$, $a$[{"paragraph": "/Hay una promesa en la Biblia \n Que es para ti y para mi/ \n /Cielo nuevo y tierra nueva \n donde vamos a vivir/"}, {"paragraph": "/Saltando hermanos saltando \n Saltando hermanos saltando \n Saltando hermanos saltando \n Como corderos de la manada/"}, {"paragraph": "Así, así, así,  \n así se alaba a Dios \n Así, así, así,  \n así se alaba a Dios \n Pero que lindo se ve  \n el pueblo de Dios"}, {"paragraph": "Maravilloso se ve el  \n pueblo de Dios  \n Pero que alegre se ve  \n el pueblo de Dios \n Pero que chévere se ve  \n el pueblo de Dios"}, {"paragraph": "/Y dando la media vueltita \n Y dando la media vueltita \n Y dando la media vueltita \n La vuelta entera de la victoria/"}]$a$::jsonb, $a$[]$a$::jsonb, $a$HAY UNA PROMESA EN LA BIBLIA.json$a$)
